//! Runtime for code generated by `ujuc protocol rust`. The format is
//! specified in `uju/protocol/wire-format.md`.
//!
//! Every struct and message `Foo` generates two types:
//!
//! - `Foo`, the owned value: `encoded_size`, `encode` into a caller-provided
//!   buffer, and `Foo::decode`, which validates and copies out.
//! - `FooView`, which reads an encoded value in place once `FooView::decode`
//!   has validated it. A fixed-size object's view is an align-1 [`Cell`]
//!   borrowed as `&'a FooView`, so packed collections of it are slices; a
//!   variable-size object's view is `FooView<'a>`, a `Copy` handle on its
//!   byte range.
//!
//! Collections are views as well: [`Packed`] for fixed-size items, [`Counted`]
//! for items of no size, and [`Prefixed`] or [`PrefixedMap`] for
//! variable-size ones.
//!
//! Everything under [`de`] and [`en`], and the `unsafe` constructors, is meant
//! for generated code.

use std::fmt;
use std::iter::FusedIterator;
use std::marker::PhantomData;
use std::ptr::NonNull;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

pub use crate::ecs::entity::Entity;

/// The largest encoded message, in bytes.
pub const MAX_SIZE: usize = u16::MAX as usize;

/// The latest `timestamp`, 9999-12-31T23:59:59.999999Z, in microseconds
/// since the Unix epoch.
pub const MAX_TIMESTAMP_MICROS: u64 = 253_402_300_799_999_999;

/// The longest `duration`, 10000 Julian years, in microseconds.
pub const MAX_DURATION_MICROS: u64 = 315_576_000_000_000_000;

/// An owned value that can be encoded.
pub trait Encode {
    /// The largest encoding of any value, `None` when only [`MAX_SIZE`]
    /// bounds it.
    const MAX_ENCODED_SIZE: Option<usize>;

    /// The exact number of bytes [`Encode::encode`] writes.
    fn encoded_size(&self) -> usize;

    /// Writes the encoding to the start of `buf`, returning its length.
    /// `buf` must hold at least [`Encode::encoded_size`] bytes; on error, its
    /// contents are unspecified.
    fn encode(&self, buf: &mut [u8]) -> Result<usize, EncodeError>;

    /// Appends the encoding without the message size check; nested values
    /// are written through this.
    #[doc(hidden)]
    fn write(&self, w: &mut en::Writer<'_>) -> Result<(), EncodeError>;
}

/// A view validated out of exactly the bytes of one encoding.
pub trait Decode<'a>: Sized {
    fn decode(buf: &'a [u8]) -> Result<Self, DecodeError>;
}

/// Checks that `buf` holds a valid encoding of a view's type. `at` is where
/// `buf` starts in the message, for error offsets.
pub trait Validate {
    fn validate_at(buf: &[u8], at: usize) -> Result<(), DecodeError>;
}

/// A message, named as in the schema.
pub trait Message {
    /// The fully qualified name: `foo.bar.MyRequest`.
    const NAME: &'static str;
}

/// A role a message names as an endpoint, as `role::Sim`.
pub trait Role {
    /// The name in the schema: `sim`.
    const NAME: &'static str;
}

/// The roles a message names as endpoints.
pub mod role {
    macro_rules! roles {
        ($($(#[$doc:meta])* $role:ident = $name:literal,)*) => {
            $(
                $(#[$doc])*
                #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
                pub struct $role;

                impl super::Role for $role {
                    const NAME: &'static str = $name;
                }
            )*
        };
    }

    roles! {
        /// A player's game.
        Client = "client",
        /// The server clients log in through.
        Entry = "entry",
        /// The server clients stay connected to, relaying to sims and hubs.
        Edge = "edge",
        /// A server simulating cells of the world.
        Sim = "sim",
        /// A server holding hub objects.
        Hub = "hub",
    }
}

/// A message travelling from `From` to `To`. Each role pair numbers its
/// messages densely from 1, by qualified name.
pub trait Link<From: Role, To: Role>: Message {
    const ID: u16;
}

/// A hub kind, declared as `hub(Key) Name { ... }`. Its body is the
/// object's state, and the type implementing this. A hub object is found by
/// its kind and key.
pub trait HubKind {
    /// The key naming one object of the kind.
    type Key;
    /// The kind's id, dense from 1 over every hub kind by qualified name.
    const ID: u16;
    /// The fully qualified name: `foo.bar.Guild`.
    const NAME: &'static str;
}

/// A message to a hub kind's objects, sent with the key of the object it
/// goes to, as `send_hub(key, &msg)`. A role sending one need not have the
/// kind, so this names only the key.
pub trait ToHub: Message {
    /// The receiving kind's key.
    type Key;
}

/// A message to a hub kind's objects, where the kind is known: on hubs,
/// which store it, and on sims, which cache it. The kind's id and the key
/// find the object's slot.
pub trait HubMessage: ToHub {
    type Kind: HubKind<Key = Self::Key>;
}

/// What an edge needs to relay one message without reading its body. A
/// relay table holds one per message of a role pair, at index `id - 1`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Relay {
    /// The body's size when every encoding has it, `None` when it varies.
    pub size: Option<u32>,
    /// Where a message to a hub goes, `None` for any other.
    pub hub: Option<HubRoute>,
}

/// The hub kind a message goes to, and the size of the key that follows
/// its id in the envelope.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct HubRoute {
    /// The kind's id, as [`HubKind::ID`].
    pub kind: u16,
    /// The key's encoded size, which is fixed.
    pub key_size: u32,
}

impl Relay {
    /// The entry for message `id` in `table`, `None` when no message has
    /// that id.
    pub fn find(table: &[Relay], id: u16) -> Option<&Relay> {
        table.get(usize::from(id).checked_sub(1)?)
    }
}

/// A fixed-size value read in place.
///
/// # Safety
///
/// The type must be laid out as a byte array (align 1, no padding): `u8`,
/// `i8`, or a `#[repr(transparent)]` or `#[repr(C)]` wrapper of other cells.
/// A reference to it may only be made from bytes validated as its type.
pub unsafe trait Cell: Sized + 'static {
    type Value<'a>;

    fn get(&self) -> Self::Value<'_>;
}

/// A cell every byte pattern is a valid value of, so it can be read before
/// validation.
///
/// # Safety
///
/// Reading the cell from arbitrary bytes must be sound.
pub unsafe trait Plain: Cell {}

/// A variable-size value spanning its whole byte range.
pub trait Var<'a>: Sized {
    /// # Safety
    ///
    /// `bytes` must have been validated as this type.
    unsafe fn read(bytes: &'a [u8]) -> Self;
}

/// A generated enum, stored as its repr.
///
/// # Safety
///
/// `Bytes` must be `[u8; N]`, `N` being the repr's size.
pub unsafe trait Enum: Copy + 'static {
    type Bytes: Copy + AsRef<[u8]> + 'static;

    fn from_bytes(bytes: Self::Bytes) -> Option<Self>;

    fn to_bytes(self) -> Self::Bytes;
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
#[error("cannot encode `{field}`: {kind}")]
pub struct EncodeError {
    /// The field at fault, as `Type.field`, or the message that doesn't fit
    /// the buffer or grew too large.
    pub field: &'static str,
    pub kind: EncodeErrorKind,
}

impl EncodeError {
    pub fn new(field: &'static str, kind: EncodeErrorKind) -> Self {
        EncodeError { field, kind }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EncodeErrorKind {
    /// The message, a length, or an offset exceeds [`MAX_SIZE`].
    TooLarge,
    /// The buffer is shorter than the encoding.
    Buffer,
    /// A length is outside `min_length..=max_length`.
    Length,
    /// An integer or float is outside `min..=max`, or a timestamp or
    /// duration outside the range its type can hold.
    Range,
    /// A float is NaN or infinite where the schema forbids it.
    Float,
}

impl fmt::Display for EncodeErrorKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            EncodeErrorKind::TooLarge => "exceeds the message size limit",
            EncodeErrorKind::Buffer => "buffer is too small",
            EncodeErrorKind::Length => "length is out of range",
            EncodeErrorKind::Range => "value is out of range",
            EncodeErrorKind::Float => "float is NaN or infinite",
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
#[error("invalid `{field}` at byte {offset}: {kind}")]
pub struct DecodeError {
    /// Where the fault was found, from the start of the message.
    pub offset: u16,
    /// The field or type at fault, as `Type.field` or `Type`.
    pub field: &'static str,
    pub kind: DecodeErrorKind,
}

impl DecodeError {
    pub fn new(offset: usize, field: &'static str, kind: DecodeErrorKind) -> Self {
        DecodeError {
            offset: offset.min(u16::MAX as usize) as u16,
            field,
            kind,
        }
    }

    /// No message has this id.
    pub fn unknown(id: u16) -> Self {
        DecodeError::new(0, "", DecodeErrorKind::UnknownId(id))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DecodeErrorKind {
    /// The buffer exceeds [`MAX_SIZE`].
    TooLarge,
    /// Too short, or too long, for its layout.
    Size,
    /// A boundary is out of range or before the previous one.
    Boundary,
    /// A collection doesn't fill its range, or a length is outside
    /// `min_length..=max_length`.
    Length,
    /// A bit or slot that must be empty isn't.
    Padding,
    /// A `bool` byte other than `0` or `1`.
    Bool,
    /// An undeclared enum value.
    Enum,
    /// An `entity` whose generation is zero.
    Entity,
    /// An integer or float outside `min..=max`, or a timestamp or duration
    /// past the largest its type allows.
    Range,
    /// A NaN or infinite float where the schema forbids it.
    Float,
    /// A string that isn't UTF-8.
    Utf8,
    /// An undeclared union tag.
    Tag,
    /// No message has this id.
    UnknownId(u16),
}

impl fmt::Display for DecodeErrorKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            DecodeErrorKind::TooLarge => f.write_str("exceeds the message size limit"),
            DecodeErrorKind::Size => f.write_str("wrong size"),
            DecodeErrorKind::Boundary => f.write_str("boundary out of range"),
            DecodeErrorKind::Length => f.write_str("length out of range"),
            DecodeErrorKind::Padding => f.write_str("unused bits or bytes are set"),
            DecodeErrorKind::Bool => f.write_str("bool is neither 0 nor 1"),
            DecodeErrorKind::Enum => f.write_str("undeclared enum value"),
            DecodeErrorKind::Entity => f.write_str("entity generation is zero"),
            DecodeErrorKind::Range => f.write_str("value out of range"),
            DecodeErrorKind::Float => f.write_str("float is NaN or infinite"),
            DecodeErrorKind::Utf8 => f.write_str("string is not UTF-8"),
            DecodeErrorKind::Tag => f.write_str("undeclared union tag"),
            DecodeErrorKind::UnknownId(id) => write!(f, "unknown message id {id}"),
        }
    }
}

// ---------------------------------------------------------------------------
// Cells

macro_rules! scalar {
    ($($(#[$doc:meta])* $name:ident($ty:ty, $size:literal);)*) => {$(
        $(#[$doc])*
        #[repr(transparent)]
        #[derive(Clone, Copy, PartialEq, Eq, Hash)]
        pub struct $name([u8; $size]);

        impl $name {
            #[inline]
            pub fn get(&self) -> $ty {
                <$ty>::from_le_bytes(self.0)
            }
        }

        unsafe impl Cell for $name {
            type Value<'a> = $ty;

            #[inline]
            fn get(&self) -> $ty {
                <$ty>::from_le_bytes(self.0)
            }
        }

        unsafe impl Plain for $name {}

        impl fmt::Debug for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                fmt::Debug::fmt(&self.get(), f)
            }
        }
    )*};
}

scalar! {
    /// A little-endian `u16`.
    U16(u16, 2);
    /// A little-endian `u32`.
    U32(u32, 4);
    /// A little-endian `u64`.
    U64(u64, 8);
    /// A little-endian `i16`.
    I16(i16, 2);
    /// A little-endian `i32`.
    I32(i32, 4);
    /// A little-endian `i64`.
    I64(i64, 8);
    /// A little-endian `f32`.
    F32(f32, 4);
    /// A little-endian `f64`.
    F64(f64, 8);
}

unsafe impl Cell for u8 {
    type Value<'a> = u8;

    #[inline]
    fn get(&self) -> u8 {
        *self
    }
}

unsafe impl Plain for u8 {}

unsafe impl Cell for i8 {
    type Value<'a> = i8;

    #[inline]
    fn get(&self) -> i8 {
        *self
    }
}

unsafe impl Plain for i8 {}

/// A `bool` stored as a byte, as in collections and arrays.
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct Bool([u8; 1]);

impl Bool {
    #[inline]
    pub fn get(&self) -> bool {
        self.0[0] != 0
    }
}

unsafe impl Cell for Bool {
    type Value<'a> = bool;

    #[inline]
    fn get(&self) -> bool {
        self.0[0] != 0
    }
}

impl fmt::Debug for Bool {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.get(), f)
    }
}

/// An [`Entity`]: its index, then its non-zero generation.
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct EntityCell([u8; 8]);

unsafe impl Cell for EntityCell {
    type Value<'a> = Entity;

    #[inline]
    fn get(&self) -> Entity {
        // Little-endian index then generation is exactly `to_bits`.
        Entity::from_bits(u64::from_le_bytes(self.0))
    }
}

impl fmt::Debug for EntityCell {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.get(), f)
    }
}

/// A `timestamp`: microseconds since the Unix epoch, read as a
/// [`SystemTime`].
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct TimestampCell([u8; 8]);

impl TimestampCell {
    /// Every valid value fits any target's `SystemTime`. A value past
    /// [`MAX_TIMESTAMP_MICROS`], only read when a `decode_unchecked` was
    /// handed invalid bytes, reads as a later time, or panics where
    /// `SystemTime` can't hold it.
    #[inline]
    pub fn get(&self) -> SystemTime {
        let micros = Duration::from_micros(u64::from_le_bytes(self.0));
        match UNIX_EPOCH.checked_add(micros) {
            Some(time) => time,
            None => unreachable!("timestamp cells hold validated values"),
        }
    }
}

unsafe impl Cell for TimestampCell {
    type Value<'a> = SystemTime;

    #[inline]
    fn get(&self) -> SystemTime {
        TimestampCell::get(self)
    }
}

impl fmt::Debug for TimestampCell {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.get(), f)
    }
}

/// A `duration`: microseconds, read as a [`Duration`].
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct DurationCell([u8; 8]);

impl DurationCell {
    #[inline]
    pub fn get(&self) -> Duration {
        Duration::from_micros(u64::from_le_bytes(self.0))
    }
}

unsafe impl Cell for DurationCell {
    type Value<'a> = Duration;

    #[inline]
    fn get(&self) -> Duration {
        DurationCell::get(self)
    }
}

impl fmt::Debug for DurationCell {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.get(), f)
    }
}

/// An unsigned cell holding a biased integer.
pub trait Stored: Cell {
    fn raw(&self) -> u64;
}

impl Stored for u8 {
    #[inline]
    fn raw(&self) -> u64 {
        *self as u64
    }
}

impl Stored for U16 {
    #[inline]
    fn raw(&self) -> u64 {
        self.get() as u64
    }
}

impl Stored for U32 {
    #[inline]
    fn raw(&self) -> u64 {
        self.get() as u64
    }
}

/// An integer type a biased cell decodes to.
pub trait Int: Copy + 'static {
    fn unbias(min: i128, raw: u64) -> Self;
}

macro_rules! int {
    ($($ty:ty)*) => {$(
        impl Int for $ty {
            #[inline]
            fn unbias(min: i128, raw: u64) -> Self {
                (min + raw as i128) as $ty
            }
        }
    )*};
}

int!(i8 i16 i32 i64 u8 u16 u32 u64);

/// A `T` stored as `value - MIN` in the narrower cell `S`.
#[repr(transparent)]
pub struct Biased<T, S, const MIN: i128>(S, PhantomData<T>);

impl<T, S: Copy, const MIN: i128> Clone for Biased<T, S, MIN> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<T, S: Copy, const MIN: i128> Copy for Biased<T, S, MIN> {}

impl<T: Int, S: Stored, const MIN: i128> Biased<T, S, MIN> {
    #[inline]
    pub fn get(&self) -> T {
        T::unbias(MIN, self.0.raw())
    }
}

unsafe impl<T: Int, S: Stored, const MIN: i128> Cell for Biased<T, S, MIN> {
    type Value<'a> = T;

    #[inline]
    fn get(&self) -> T {
        T::unbias(MIN, self.0.raw())
    }
}

impl<T: Int + fmt::Debug, S: Stored, const MIN: i128> fmt::Debug for Biased<T, S, MIN> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.get(), f)
    }
}

/// A string of exactly `N` bytes.
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct FixedStr<const N: usize>([u8; N]);

impl<const N: usize> FixedStr<N> {
    #[inline]
    pub fn get(&self) -> &str {
        // SAFETY: cells are only made from validated bytes.
        unsafe { str::from_utf8_unchecked(&self.0) }
    }
}

unsafe impl<const N: usize> Cell for FixedStr<N> {
    type Value<'a> = &'a str;

    #[inline]
    fn get(&self) -> &str {
        FixedStr::get(self)
    }
}

impl<const N: usize> fmt::Debug for FixedStr<N> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(self.get(), f)
    }
}

unsafe impl<C: Cell, const N: usize> Cell for [C; N] {
    type Value<'a> = &'a [C; N];

    #[inline]
    fn get(&self) -> &[C; N] {
        self
    }
}

unsafe impl<C: Plain, const N: usize> Plain for [C; N] {}

/// A map entry: the key, then the value.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct Entry<K, V>(K, V);

impl<K: Cell, V: Cell> Entry<K, V> {
    #[inline]
    pub fn key(&self) -> K::Value<'_> {
        self.0.get()
    }

    #[inline]
    pub fn value(&self) -> V::Value<'_> {
        self.1.get()
    }
}

unsafe impl<K: Cell, V: Cell> Cell for Entry<K, V> {
    type Value<'a> = (K::Value<'a>, V::Value<'a>);

    #[inline]
    fn get(&self) -> Self::Value<'_> {
        (self.0.get(), self.1.get())
    }
}

impl<K: Cell + fmt::Debug, V: Cell + fmt::Debug> fmt::Debug for Entry<K, V> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_tuple("Entry")
            .field(&self.0)
            .field(&self.1)
            .finish()
    }
}

/// An enum stored as its repr.
#[repr(transparent)]
pub struct EnumCell<E: Enum>(E::Bytes, PhantomData<E>);

impl<E: Enum> Clone for EnumCell<E> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<E: Enum> Copy for EnumCell<E> {}

impl<E: Enum> EnumCell<E> {
    #[inline]
    pub fn get(&self) -> E {
        match E::from_bytes(self.0) {
            Some(value) => value,
            None => unreachable!("enum cells hold validated values"),
        }
    }
}

unsafe impl<E: Enum> Cell for EnumCell<E> {
    type Value<'a> = E;

    #[inline]
    fn get(&self) -> E {
        EnumCell::get(self)
    }
}

impl<E: Enum + fmt::Debug> fmt::Debug for EnumCell<E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.get(), f)
    }
}

/// A generated `type`: a newtype over a scalar, read from its target's cell.
pub trait Newtype: Copy + 'static {
    /// The target's cell.
    type Cell: Cell;

    fn from_cell(cell: &Self::Cell) -> Self;
}

/// A [`Newtype`] stored as its target.
#[repr(transparent)]
pub struct Typed<T: Newtype>(T::Cell, PhantomData<T>);

impl<T: Newtype> Clone for Typed<T>
where
    T::Cell: Copy,
{
    fn clone(&self) -> Self {
        *self
    }
}

impl<T: Newtype> Copy for Typed<T> where T::Cell: Copy {}

impl<T: Newtype> Typed<T> {
    #[inline]
    pub fn get(&self) -> T {
        T::from_cell(&self.0)
    }
}

// SAFETY: a transparent wrapper of a cell, so laid out as one.
unsafe impl<T: Newtype> Cell for Typed<T> {
    type Value<'a> = T;

    #[inline]
    fn get(&self) -> T {
        Typed::get(self)
    }
}

// SAFETY: valid for any bytes its target cell is valid for.
unsafe impl<T: Newtype> Plain for Typed<T> where T::Cell: Plain {}

impl<T: Newtype + fmt::Debug> fmt::Debug for Typed<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(&self.get(), f)
    }
}

/// Borrows `bytes` as a cell.
///
/// # Safety
///
/// `bytes` must be exactly `size_of::<C>()` long and validated as `C`.
#[inline]
pub unsafe fn cast<C: Cell>(bytes: &[u8]) -> &C {
    debug_assert_eq!(bytes.len(), size_of::<C>());
    // SAFETY: `C` is align 1 and laid out as `bytes`.
    unsafe { &*bytes.as_ptr().cast::<C>() }
}

/// Reads the cell `at` bytes into `buf`.
///
/// # Safety
///
/// Those bytes must have been validated as `C`.
#[inline]
pub unsafe fn read<C: Cell>(buf: &[u8], at: usize) -> C::Value<'_> {
    unsafe { cast::<C>(&buf[at..at + size_of::<C>()]) }.get()
}

/// Bit `n` of a bitmap, counting from the least significant bit of the first
/// byte.
#[inline]
pub fn bit(buf: &[u8], n: u32) -> bool {
    buf[(n / 8) as usize] >> (n % 8) & 1 != 0
}

/// The boundary of `width` bytes at `at`.
#[inline]
pub fn bound(buf: &[u8], at: usize, width: usize) -> usize {
    read_len(&buf[at..], width)
}

/// Where the `k`-th optional fixed-size value starts: `head` plus the sizes
/// of the present ones before it. `optionals` lists each one's presence bit
/// and size; passing their count gives the start of the var section.
#[inline]
pub fn offset(buf: &[u8], head: usize, optionals: &[(u32, usize)], k: usize) -> usize {
    let mut at = head;
    for &(presence, size) in &optionals[..k] {
        if bit(buf, presence) {
            at += size;
        }
    }
    at
}

/// The byte range of slot `k` of `slots`: slot `0` starts at `start`, every
/// other one at the boundary before it, and the last runs to the end. The
/// boundaries of `width` bytes start `bounds` bytes into `buf`.
#[inline]
pub fn slot(
    buf: &[u8],
    start: usize,
    bounds: usize,
    width: usize,
    slots: usize,
    k: usize,
) -> std::ops::Range<usize> {
    let begin = if k == 0 {
        start
    } else {
        bound(buf, bounds + (k - 1) * width, width)
    };
    let end = if k + 1 == slots {
        buf.len()
    } else {
        bound(buf, bounds + k * width, width)
    };
    begin..end
}

#[inline]
fn read_len(bytes: &[u8], width: usize) -> usize {
    if width == 1 {
        bytes[0] as usize
    } else {
        u16::from_le_bytes([bytes[0], bytes[1]]) as usize
    }
}

impl<'a> Var<'a> for &'a [u8] {
    #[inline]
    unsafe fn read(bytes: &'a [u8]) -> Self {
        bytes
    }
}

impl<'a> Var<'a> for &'a str {
    #[inline]
    unsafe fn read(bytes: &'a [u8]) -> Self {
        // SAFETY: validated as UTF-8.
        unsafe { str::from_utf8_unchecked(bytes) }
    }
}

