impl Float for f64 {
    #[inline]
    fn is_nan(self) -> bool {
        f64::is_nan(self)
    }

    #[inline]
    fn is_infinite(self) -> bool {
        f64::is_infinite(self)
    }
}

// ---------------------------------------------------------------------------
// Validation

/// Checks for decoders. `at` is where the checked bytes start in the message;
/// `field` names what is checked, as `Type.field`.
pub mod de {
    use super::*;

    #[inline]
    fn fail<T>(at: usize, field: &'static str, kind: DecodeErrorKind) -> Result<T, DecodeError> {
        Err(DecodeError::new(at, field, kind))
    }

    /// Reads a cell that any bytes are valid for, before validation.
    #[inline]
    pub fn plain<C: Plain>(buf: &[u8], at: usize) -> C::Value<'_> {
        // SAFETY: every byte pattern is a valid `C`.
        unsafe { read::<C>(buf, at) }
    }

    /// A whole message fits [`MAX_SIZE`].
    #[inline]
    pub fn size(buf: &[u8], field: &'static str) -> Result<(), DecodeError> {
        if buf.len() > MAX_SIZE {
            return fail(MAX_SIZE, field, DecodeErrorKind::TooLarge);
        }
        Ok(())
    }

    #[inline]
    pub fn exact(
        buf: &[u8],
        len: usize,
        at: usize,
        field: &'static str,
    ) -> Result<(), DecodeError> {
        if buf.len() != len {
            return fail(at + buf.len().min(len), field, DecodeErrorKind::Size);
        }
        Ok(())
    }

    #[inline]
    pub fn at_least(
        buf: &[u8],
        len: usize,
        at: usize,
        field: &'static str,
    ) -> Result<(), DecodeError> {
        if buf.len() < len {
            return fail(at + buf.len(), field, DecodeErrorKind::Size);
        }
        Ok(())
    }

    /// The tag read at `at` names no variant of the union `field`.
    #[cold]
    pub fn tag<T>(at: usize, field: &'static str) -> Result<T, DecodeError> {
        fail(at, field, DecodeErrorKind::Tag)
    }

    /// The slot of an absent value is empty.
    #[inline]
    pub fn empty(bytes: &[u8], at: usize, field: &'static str) -> Result<(), DecodeError> {
        if !bytes.is_empty() {
            return fail(at, field, DecodeErrorKind::Padding);
        }
        Ok(())
    }

    /// The bits of `byte` in `unused` are zero.
    #[inline]
    pub fn unused(byte: u8, unused: u8, at: usize, field: &'static str) -> Result<(), DecodeError> {
        if byte & unused != 0 {
            return fail(at, field, DecodeErrorKind::Padding);
        }
        Ok(())
    }

    /// An absent `option<bool>` has its value bit clear.
    #[inline]
    pub fn option_bool(
        buf: &[u8],
        presence: u32,
        value: u32,
        at: usize,
        field: &'static str,
    ) -> Result<(), DecodeError> {
        if !bit(buf, presence) && bit(buf, value) {
            return fail(at + (value / 8) as usize, field, DecodeErrorKind::Padding);
        }
        Ok(())
    }

    #[inline]
    pub fn boolean(byte: u8, at: usize, field: &'static str) -> Result<(), DecodeError> {
        if byte > 1 {
            return fail(at, field, DecodeErrorKind::Bool);
        }
        Ok(())
    }

    #[inline]
    pub fn enumeration<E: Enum>(
        bytes: &[u8],
        at: usize,
        field: &'static str,
    ) -> Result<(), DecodeError> {
        // SAFETY: an enum cell is plain bytes; only `get` relies on them
        // being a variant, and it isn't called here.
        let cell = unsafe { cast::<EnumCell<E>>(bytes) };
        match E::from_bytes(cell.0) {
            Some(_) => Ok(()),
            None => fail(at, field, DecodeErrorKind::Enum),
        }
    }

    /// An `entity`'s generation, its last 4 bytes, is non-zero.
    #[inline]
    pub fn entity(bytes: &[u8], at: usize, field: &'static str) -> Result<(), DecodeError> {
        if bytes[4..8] == [0; 4] {
            return fail(at + 4, field, DecodeErrorKind::Entity);
        }
        Ok(())
    }

    /// A `timestamp` is at most [`MAX_TIMESTAMP_MICROS`].
    #[inline]
    pub fn timestamp(bytes: &[u8], at: usize, field: &'static str) -> Result<(), DecodeError> {
        range(plain::<U64>(bytes, 0), 0, MAX_TIMESTAMP_MICROS, at, field)
    }

    /// A `duration` is at most [`MAX_DURATION_MICROS`].
    #[inline]
    pub fn duration(bytes: &[u8], at: usize, field: &'static str) -> Result<(), DecodeError> {
        range(plain::<U64>(bytes, 0), 0, MAX_DURATION_MICROS, at, field)
    }

    #[inline]
    pub fn utf8(bytes: &[u8], at: usize, field: &'static str) -> Result<(), DecodeError> {
        match str::from_utf8(bytes) {
            Ok(_) => Ok(()),
            Err(error) => fail(at + error.valid_up_to(), field, DecodeErrorKind::Utf8),
        }
    }

    #[inline]
    pub fn range<T: PartialOrd>(
        value: T,
        min: T,
        max: T,
        at: usize,
        field: &'static str,
    ) -> Result<(), DecodeError> {
        if value < min || value > max {
            return fail(at, field, DecodeErrorKind::Range);
        }
        Ok(())
    }

    #[inline]
    pub fn float<T: Float>(
        value: T,
        nan: bool,
        infinite: bool,
        min: T,
        max: T,
        at: usize,
        field: &'static str,
    ) -> Result<(), DecodeError> {
        if value.is_nan() {
            return if nan {
                Ok(())
            } else {
                fail(at, field, DecodeErrorKind::Float)
            };
        }
        if value.is_infinite() && !infinite {
            return fail(at, field, DecodeErrorKind::Float);
        }
        range(value, min, max, at, field)
    }

    #[inline]
    pub fn length(
        len: usize,
        min: usize,
        max: usize,
        at: usize,
        field: &'static str,
    ) -> Result<(), DecodeError> {
        if len < min || len > max {
            return fail(at, field, DecodeErrorKind::Length);
        }
        Ok(())
    }

    /// Packed items of `size` bytes fill `bytes`; returns their count.
    #[inline]
    pub fn packed(
        bytes: &[u8],
        size: usize,
        at: usize,
        field: &'static str,
    ) -> Result<usize, DecodeError> {
        if !bytes.len().is_multiple_of(size) {
            return fail(at, field, DecodeErrorKind::Length);
        }
        Ok(bytes.len() / size)
    }

    /// `bytes` is exactly a count of `width` bytes; returns it.
    #[inline]
    pub fn counted(
        bytes: &[u8],
        width: usize,
        at: usize,
        field: &'static str,
    ) -> Result<usize, DecodeError> {
        exact(bytes, width, at, field)?;
        Ok(read_len(bytes, width))
    }

    /// Prefixed items fill `bytes` exactly. Each item's bytes and offset go
    /// to `item`; returns their count.
    pub fn prefixed(
        bytes: &[u8],
        count: usize,
        prefix: usize,
        at: usize,
        field: &'static str,
        mut item: impl FnMut(&[u8], usize) -> Result<(), DecodeError>,
    ) -> Result<usize, DecodeError> {
        at_least(bytes, count, at, field)?;
        let len = read_len(bytes, count);
        let mut pos = count;
        for index in 0..len {
            if index + 1 == len {
                item(&bytes[pos..], at + pos)?;
                return Ok(len);
            }
            if bytes.len() - pos < prefix {
                return fail(at + pos, field, DecodeErrorKind::Length);
            }
            let size = read_len(&bytes[pos..], prefix);
            pos += prefix;
            if bytes.len() - pos < size {
                return fail(at + pos, field, DecodeErrorKind::Length);
            }
            item(&bytes[pos..pos + size], at + pos)?;
            pos += size;
        }
        // Only an empty collection gets here: its count is all there is.
        if pos != bytes.len() {
            return fail(at + pos, field, DecodeErrorKind::Length);
        }
        Ok(0)
    }

    /// Reads the `N` boundaries of `width` bytes starting `offset` bytes into
    /// `buf`, checking each lies between the previous one (`start` for the
    /// first) and the end of `buf`.
    #[inline]
    pub fn boundaries<const N: usize>(
        buf: &[u8],
        offset: usize,
        width: usize,
        start: usize,
        at: usize,
        field: &'static str,
    ) -> Result<[usize; N], DecodeError> {
        let mut ends = [0; N];
        let mut previous = start;
        for (index, end) in ends.iter_mut().enumerate() {
            let pos = offset + index * width;
            *end = bound(buf, pos, width);
            if *end < previous || *end > buf.len() {
                return fail(at + pos, field, DecodeErrorKind::Boundary);
            }
            previous = *end;
        }
        Ok(ends)
    }
}

// ---------------------------------------------------------------------------
// Encoding

/// Checks and writers for encoders. `field` names what is checked, as
/// `Type.field`; the [`Writer`] names the message instead, since running out
/// of room is the whole message's fault.
pub mod en {
    use super::*;

    #[inline]
    fn fail<T>(field: &'static str, kind: EncodeErrorKind) -> Result<T, EncodeError> {
        Err(EncodeError::new(field, kind))
    }

    /// Writes `value` to the start of `buf` as a whole message.
    #[inline]
    pub fn encode<T: Encode + ?Sized>(
        value: &T,
        buf: &mut [u8],
        name: &'static str,
    ) -> Result<usize, EncodeError> {
        let mut w = Writer::new(buf, name);
        value.write(&mut w)?;
        if w.pos() > MAX_SIZE {
            return fail(name, EncodeErrorKind::TooLarge);
        }
        Ok(w.pos())
    }

    /// Appends to a borrowed buffer, failing once it runs out.
    pub struct Writer<'a> {
        buf: &'a mut [u8],
        pos: usize,
        name: &'static str,
    }

    impl<'a> Writer<'a> {
        #[inline]
        pub fn new(buf: &'a mut [u8], name: &'static str) -> Self {
            Writer { buf, pos: 0, name }
        }

        /// The bytes written so far.
        #[inline]
        pub fn pos(&self) -> usize {
            self.pos
        }

        #[inline]
        pub fn put(&mut self, bytes: &[u8]) -> Result<(), EncodeError> {
            let end = self.pos + bytes.len();
            match self.buf.get_mut(self.pos..end) {
                Some(dst) => {
                    dst.copy_from_slice(bytes);
                    self.pos = end;
                    Ok(())
                }
                None => fail(self.name, EncodeErrorKind::Buffer),
            }
        }

        /// Appends `len` zeros to fill in later; returns where they start.
        #[inline]
        pub fn zeros(&mut self, len: usize) -> Result<usize, EncodeError> {
            let start = self.pos;
            let end = start + len;
            match self.buf.get_mut(start..end) {
                Some(dst) => {
                    dst.fill(0);
                    self.pos = end;
                    Ok(start)
                }
                None => fail(self.name, EncodeErrorKind::Buffer),
            }
        }

        /// Appends `len` as a count or length of `width` bytes.
        #[inline]
        pub fn len(&mut self, width: usize, len: usize) -> Result<(), EncodeError> {
            let at = self.zeros(width)?;
            self.patch(at, width, len)
        }

        /// Writes `value` over the `width` bytes at `at`, already appended.
        #[inline]
        pub fn patch(&mut self, at: usize, width: usize, value: usize) -> Result<(), EncodeError> {
            if width == 1 {
                let Ok(value) = u8::try_from(value) else {
                    return fail(self.name, EncodeErrorKind::TooLarge);
                };
                self.buf[at] = value;
            } else {
                let Ok(value) = u16::try_from(value) else {
                    return fail(self.name, EncodeErrorKind::TooLarge);
                };
                self.buf[at..at + 2].copy_from_slice(&value.to_le_bytes());
            }
            Ok(())
        }

        /// Ends a slot: writes the boundary of `width` bytes at `at` as the
        /// current end of the object starting at `start`.
        #[inline]
        pub fn end(&mut self, at: usize, start: usize, width: usize) -> Result<(), EncodeError> {
            let end = self.pos - start;
            self.patch(at, width, end)
        }
    }

    #[inline]
    pub fn range<T: PartialOrd>(
        value: T,
        min: T,
        max: T,
        field: &'static str,
    ) -> Result<(), EncodeError> {
        if value < min || value > max {
            return fail(field, EncodeErrorKind::Range);
        }
        Ok(())
    }

    #[inline]
    pub fn float<T: Float>(
        value: T,
        nan: bool,
        infinite: bool,
        min: T,
        max: T,
        field: &'static str,
    ) -> Result<(), EncodeError> {
        if value.is_nan() {
            return if nan {
                Ok(())
            } else {
                fail(field, EncodeErrorKind::Float)
            };
        }
        if value.is_infinite() && !infinite {
            return fail(field, EncodeErrorKind::Float);
        }
        range(value, min, max, field)
    }

    /// A `timestamp`'s encoding: microseconds since the Unix epoch, any
    /// finer precision truncated. Fails before the epoch or past
    /// [`MAX_TIMESTAMP_MICROS`].
    #[inline]
    pub fn timestamp(value: SystemTime, field: &'static str) -> Result<[u8; 8], EncodeError> {
        match value.duration_since(UNIX_EPOCH) {
            Ok(since) => micros(since, MAX_TIMESTAMP_MICROS, field),
            Err(_) => fail(field, EncodeErrorKind::Range),
        }
    }

    /// A `duration`'s encoding: microseconds, any finer precision
    /// truncated. Fails past [`MAX_DURATION_MICROS`].
    #[inline]
    pub fn duration(value: Duration, field: &'static str) -> Result<[u8; 8], EncodeError> {
        micros(value, MAX_DURATION_MICROS, field)
    }

    #[inline]
    fn micros(value: Duration, max: u64, field: &'static str) -> Result<[u8; 8], EncodeError> {
        let micros = value.as_micros();
        if micros > max as u128 {
            return fail(field, EncodeErrorKind::Range);
        }
        Ok((micros as u64).to_le_bytes())
    }

    #[inline]
    pub fn length(
        len: usize,
        min: usize,
        max: usize,
        field: &'static str,
    ) -> Result<(), EncodeError> {
        if len < min || len > max {
            return fail(field, EncodeErrorKind::Length);
        }
        Ok(())
    }

    /// Appends prefixed items: their count, then each one written by `item`
    /// behind its length, but the last.
    pub fn prefixed<I: ExactSizeIterator>(
        w: &mut Writer<'_>,
        items: I,
        count: usize,
        prefix: usize,
        mut item: impl FnMut(&mut Writer<'_>, I::Item) -> Result<(), EncodeError>,
    ) -> Result<(), EncodeError> {
        let len = items.len();
        w.len(count, len)?;
        for (index, value) in items.enumerate() {
            if index + 1 == len {
                item(w, value)?;
            } else {
                let at = w.zeros(prefix)?;
                item(w, value)?;
                let size = w.pos() - at - prefix;
                w.patch(at, prefix, size)?;
            }
        }
        Ok(())
    }

    /// The size of prefixed items, each `size` bytes.
    pub fn prefixed_size<I: ExactSizeIterator>(
        items: I,
        count: usize,
        prefix: usize,
        size: impl FnMut(I::Item) -> usize,
    ) -> usize {
        let len = items.len();
        count + items.map(size).sum::<usize>() + len.saturating_sub(1) * prefix
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cells_read_little_endian() {
        let bytes = [0x01, 0x02, 0x03, 0x04];
        unsafe {
            assert_eq!(read::<U16>(&bytes, 1), 0x0302);
            assert_eq!(read::<I32>(&bytes, 0), 0x0403_0201);
            assert_eq!(read::<Biased<i32, u8, -100>>(&[107], 0), 7);
            assert_eq!(read::<Biased<u32, U16, 1000>>(&[0x01, 0x00], 0), 1001);
        }
    }

    #[test]
    fn entities_read_index_then_generation() {
        let entity = Entity::from_bits(7 | (3 << 32));
        let bytes = entity.to_bits().to_le_bytes();
        assert_eq!(bytes, [7, 0, 0, 0, 3, 0, 0, 0]);
        assert_eq!(unsafe { read::<EntityCell>(&bytes, 0) }, entity);
        assert!(de::entity(&[7, 0, 0, 0, 0, 0, 0, 0], 0, "t").is_err());
    }

    #[test]
    fn timestamps_are_micros_since_the_epoch() {
        let at = |micros: u64| UNIX_EPOCH + Duration::from_micros(micros);
        let max = at(MAX_TIMESTAMP_MICROS);
        for (time, micros) in [(UNIX_EPOCH, 0), (max, MAX_TIMESTAMP_MICROS)] {
            let bytes = en::timestamp(time, "t").unwrap();
            assert_eq!(bytes, micros.to_le_bytes());
            assert_eq!(unsafe { read::<TimestampCell>(&bytes, 0) }, time);
            assert_eq!(de::timestamp(&bytes, 0, "t"), Ok(()));
        }
        // Finer precision is truncated toward the epoch.
        let fine = at(1_500_000) + Duration::from_nanos(999);
        assert_eq!(en::timestamp(fine, "t"), Ok(1_500_000u64.to_le_bytes()));

        let range = EncodeError::new("t", EncodeErrorKind::Range);
        assert_eq!(
            en::timestamp(max + Duration::from_micros(1), "t"),
            Err(range)
        );
        assert_eq!(
            en::timestamp(max + Duration::from_nanos(999), "t"),
            Ok(MAX_TIMESTAMP_MICROS.to_le_bytes())
        );
        assert_eq!(
            en::timestamp(UNIX_EPOCH - Duration::from_nanos(1), "t"),
            Err(range)
        );
        assert_eq!(
            de::timestamp(&(MAX_TIMESTAMP_MICROS + 1).to_le_bytes(), 2, "t"),
            Err(DecodeError::new(2, "t", DecodeErrorKind::Range))
        );
    }

    #[test]
    fn durations_are_micros() {
        let max = Duration::from_micros(MAX_DURATION_MICROS);
        for (duration, micros) in [(Duration::ZERO, 0), (max, MAX_DURATION_MICROS)] {
            let bytes = en::duration(duration, "t").unwrap();
            assert_eq!(bytes, micros.to_le_bytes());
            assert_eq!(unsafe { read::<DurationCell>(&bytes, 0) }, duration);
            assert_eq!(de::duration(&bytes, 0, "t"), Ok(()));
        }
        assert_eq!(
            en::duration(Duration::from_nanos(2_999), "t"),
            Ok(2u64.to_le_bytes())
        );

        let range = EncodeError::new("t", EncodeErrorKind::Range);
        assert_eq!(
            en::duration(max + Duration::from_micros(1), "t"),
            Err(range)
        );
        assert_eq!(en::duration(Duration::MAX, "t"), Err(range));
        assert_eq!(
            de::duration(&(MAX_DURATION_MICROS + 1).to_le_bytes(), 2, "t"),
            Err(DecodeError::new(2, "t", DecodeErrorKind::Range))
        );
        // Unchecked bytes past the range still read without overflow.
        assert_eq!(
            unsafe { read::<DurationCell>(&u64::MAX.to_le_bytes(), 0) },
            Duration::from_micros(u64::MAX)
        );
    }

    #[test]
    fn undeclared_tags_fail_at_their_offset() {
        let error = de::tag::<()>(3, "U").unwrap_err();
        assert_eq!(error, DecodeError::new(3, "U", DecodeErrorKind::Tag));
        assert_eq!(
            error.to_string(),
            "invalid `U` at byte 3: undeclared union tag"
        );
    }

    #[test]
    fn typed_cells_read_their_target() {
        #[derive(Debug, Clone, Copy, PartialEq)]
        struct PartyId(u64);

        impl Newtype for PartyId {
            type Cell = U64;

            fn from_cell(cell: &U64) -> Self {
                PartyId(Cell::get(cell))
            }
        }

        assert_eq!(size_of::<Typed<PartyId>>(), size_of::<U64>());
        assert_eq!(align_of::<Typed<PartyId>>(), align_of::<U64>());
        let bytes = [0, 0x01, 0x02, 0, 0, 0, 0, 0, 0x03];
        let id = unsafe { read::<Typed<PartyId>>(&bytes, 1) };
        assert_eq!(id, PartyId(0x0300_0000_0000_0201));
        assert_eq!(de::plain::<Typed<PartyId>>(&bytes, 0), PartyId(0x0002_0100));
        let cell = unsafe { cast::<Typed<PartyId>>(&bytes[1..]) };
        assert_eq!(format!("{cell:?}"), "PartyId(216172782113784321)");
    }

    #[test]
    fn optional_offsets_skip_absent_values() {
        // Bits 0 and 2 present.
        let buf = [0b101];
        let optionals = [(0, 2), (1, 4), (2, 1)];
        assert_eq!(offset(&buf, 1, &optionals, 0), 1);
        assert_eq!(offset(&buf, 1, &optionals, 1), 3);
        assert_eq!(offset(&buf, 1, &optionals, 2), 3);
        assert_eq!(offset(&buf, 1, &optionals, 3), 4);
    }

    #[test]
    fn slots_run_between_boundaries() {
        // Boundaries 3 and 5 at byte 0; the var section starts at 2.
        let buf = [3, 5, 0, 0, 0, 0, 0, 0];
        assert_eq!(slot(&buf, 2, 0, 1, 3, 0), 2..3);
        assert_eq!(slot(&buf, 2, 0, 1, 3, 1), 3..5);
        assert_eq!(slot(&buf, 2, 0, 1, 3, 2), 5..8);
        assert_eq!(slot(&buf, 2, 0, 1, 1, 0), 2..8);
    }

    #[test]
    fn prefixed_items_round_trip() {
        let items = ["a", "bc", "def"];
        let mut buf = [0; 16];
        let mut w = en::Writer::new(&mut buf, "t");
        en::prefixed(&mut w, items.iter(), 1, 1, |w, item| w.put(item.as_bytes())).unwrap();
        let len = w.pos();
        let out = &buf[..len];
        assert_eq!(out, [3, 1, b'a', 2, b'b', b'c', b'd', b'e', b'f']);
        assert_eq!(
            en::prefixed_size(items.iter(), 1, 1, |item| item.len()),
            out.len()
        );

        let mut seen = Vec::new();
        let count = de::prefixed(out, 1, 1, 0, "t", |bytes, _| {
            seen.push(bytes.to_vec());
            Ok(())
        })
        .unwrap();
        assert_eq!(count, 3);
        assert_eq!(seen, [b"a".to_vec(), b"bc".to_vec(), b"def".to_vec()]);

        let view: Prefixed<'_, &str, 1, 1> = unsafe { Var::read(out) };
        assert_eq!(view.iter().collect::<Vec<_>>(), items);
    }

    #[test]
    fn prefixed_items_must_fill_their_range() {
        let ok = |bytes: &[u8]| de::prefixed(bytes, 1, 1, 0, "t", |_, _| Ok(()));
        assert_eq!(ok(&[0]), Ok(0));
        assert!(ok(&[0, 1]).is_err(), "trailing bytes after an empty count");
        assert!(ok(&[2, 5, 1]).is_err(), "prefix past the end");
        assert!(ok(&[]).is_err(), "no count");
    }

    #[test]
    fn boundaries_never_decrease() {
        let buf = [4, 3, 0, 0, 0];
        let check = |buf: &[u8]| de::boundaries::<2>(buf, 0, 1, 2, 0, "t");
        assert!(check(&buf).is_err());
        assert_eq!(check(&[2, 4, 0, 0, 0]), Ok([2, 4]));
        assert!(check(&[2, 6, 0, 0, 0]).is_err(), "past the end");
    }

    #[test]
    fn writers_refuse_to_overrun() {
        let mut buf = [0; 3];
        let mut w = en::Writer::new(&mut buf, "t");
        w.put(&[1, 2]).unwrap();
        let error = w.put(&[3, 4]).unwrap_err();
        assert_eq!(error, EncodeError::new("t", EncodeErrorKind::Buffer));
        assert_eq!(w.pos(), 2);
        assert_eq!(w.len(1, 256).unwrap_err().kind, EncodeErrorKind::TooLarge);
    }

    #[test]
    fn relays_are_found_by_id_from_1() {
        let table = [
            Relay {
                size: Some(4),
                hub: None,
            },
            Relay {
                size: None,
                hub: Some(HubRoute {
                    kind: 2,
                    key_size: 8,
                }),
            },
        ];
        assert_eq!(Relay::find(&table, 0), None, "no message is 0");
        assert_eq!(Relay::find(&table, 1), Some(&table[0]));
        assert_eq!(Relay::find(&table, 2), Some(&table[1]));
        assert_eq!(Relay::find(&table, 3), None);
    }
}
